update public.categories set name = 'Home Automation', tagline = 'Comfort at a touch', intro = 'Motorised curtains and blinds with smart-home control, so light and privacy are a tap — or a voice command — away.', subtypes = array['Motorised curtains','Motorised blinds','Smart home control']::text[] where slug = 'home-automation';
update public.categories set name = 'Gym Mats & Specialty', tagline = 'Built to work hard', intro = 'Rubber and gym mats, PVC stud flooring for ramps and parking, floor protectors and heat insulation — practical surfaces for demanding spaces.', subtypes = array['Rubber & gym mats','PVC stud flooring','Floor protectors','Heat insulation','Bubble wraps']::text[] where slug = 'specialty-solutions';

update public.page_sections set eyebrow = 'Patna · Since 1984', heading = 'Your home, your story.', body = 'Curtains, floors, walls and furniture — chosen with you and fitted by our own team, the way we''ve furnished homes and businesses across Patna for over forty years.', cta_label = 'Explore products', items = '[]'::jsonb where page = 'home' and key = 'hero';
update public.page_sections set eyebrow = 'Since 1984', heading = 'Furnishing relationships, not just rooms.', body = 'What began in 1984 as a furnishing shop on S.P. Verma Road now dresses homes, hotels, hospitals, schools and offices across Bihar — from the first measurement to the final fitting.', cta_label = null, items = '[]'::jsonb where page = 'home' and key = 'story';
