update public.page_sections set eyebrow = null, heading = 'Let''s bring your space to life.', body = 'Tell us what you''re planning. We''ll visit, measure and suggest options that suit your space and your budget.', cta_label = 'Make an enquiry', items = '[]'::jsonb where page = 'home' and key = 'cta';
update public.page_sections set eyebrow = 'About us', heading = 'Furnishing homes and businesses since 1984.', body = 'New Ankur Furnishers began as a furnishing shop in the heart of Patna, and has spent four decades doing one thing well: helping people create spaces that feel like home.

From living rooms to hotels, hospitals to offices, we bring the same eye for materials and the same care in fitting — so every space we touch feels considered, comfortable and built to last.', cta_label = null, items = '[]'::jsonb where page = 'about' and key = 'intro';
update public.page_sections set eyebrow = null, heading = 'Why choose us', body = null, cta_label = null, items = '[{"title":"Four decades of experience","text":"Furnishing homes and businesses across Bihar since 1984."},{"title":"Fitted by our own team","text":"From measurement to installation, handled start to finish — no loose ends."},{"title":"Materials you can trust","text":"Honest, hard-wearing materials chosen to last, not just to look good on day one."},{"title":"Priced for real budgets","text":"Options at every price point, with honest advice on what''s worth it."}]'::jsonb where page = 'about' and key = 'why';
update public.page_sections set eyebrow = 'From our founder', heading = 'Forty years of furnishing relationships.', body = 'For us, a home is not just a place but a feeling — where the presence of loved ones becomes comfort, where relationships breathe, and where dreams take shape.

For over forty years, New Ankur Furnishers has tried to fill every home with warmth, belonging and memory, so that your home doesn''t only look beautiful but becomes a part of your story.

Your trust and your affection are our greatest strength. Come, let us shape the home you have in mind, together.', cta_label = 'Santosh Kumar Agrawal', items = '[]'::jsonb where page = 'about' and key = 'founder';

